<script>(function(){var d=document.documentElement;try{var t=localStorage.getItem('theme');d.setAttribute('data-theme',t==='dark'?'dark':'light');if(window.innerWidth>992&&localStorage.getItem('sidebarCollapsed')==='true'){d.classList.add('sidebar-collapsed');}}catch(e){d.setAttribute('data-theme','light');}})();</script>
